  final cubeConfig = cube;
  if (cubeConfig != null) buffer.write(cubeConfig.toYamlFragment());
  final toolsConfig = tools;
  if (toolsConfig != null && !toolsConfig.isEmpty) {
    buffer.write(toolsConfig.toYaml());
