+void main() {
+  TestWidgetsFlutterBinding.ensureInitialized();
+
+  late Directory home;
+
+  setUp(() async {
+    home = await Directory.systemTemp.createTemp('fa_links_home');
+  });
+
+  tearDown(() => home.deleteSync(recursive: true));
+
+  Future<void> writeConfig(String yaml) async {
