+<!doctype html>
+<html lang="en">
+<head>
+<meta charset="utf-8">
+<meta name="viewport" content="width=device-width, initial-scale=1">
+<title>Fa on the App Store — the store frames | Flutter Agent Harness</title>
+<meta name="description" content="Fa (Flutter Agent Harness) on the App Store: a paid release that funds development and a free-forever public TestFlight beta. The five App Store frames, generated by the golden test suite — the site never drifts from the store assets.">
+<meta name="robots" content="index, follow">
+<meta name="theme-color" content="#070a10">
+<link rel="canonical" href="https://fa1.dev/app-store/">
+<link rel="icon" href="../favicon.svg?v=2" type="image/svg+xml">
+<style>
+  :root {
+    --bg: #070a10; --panel: #0d1420; --border: #1c2637;
+    --text: #e8eef7; --dim: #93a1b5; --accent: #5eead4; --accent-2: #818cf8;
+    --mono: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, monospace;
+    --sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto,
+      "Helvetica Neue", Arial, sans-serif;
+  }
+  * { box-sizing: border-box; }
+  body {
+    margin: 0; background: var(--bg); color: var(--text);
+    font-family: var(--sans); font-size: 16px; line-height: 1.65;
+    -webkit-font-smoothing: antialiased;
+  }
+  main { max-width: 1080px; margin: 0 auto; padding: 48px 20px 96px; }
+  a { color: var(--accent); }
+  h1 { font-size: 30px; margin: 0 0 6px; }
+  h2 { font-size: 20px; margin: 40px 0 12px; }
+  p { color: var(--dim); }
+  .back { display: inline-block; margin-bottom: 24px; text-decoration: none; }
+  .lede { max-width: 720px; font-size: 1.05rem; }
+  .btn {
+    display: inline-flex; align-items: center; gap: 8px;
+    padding: 11px 20px; border-radius: 10px;
