+  final String appstore;
+
+  /// The public TestFlight beta (free forever).
+  final String testflight;
+
+  /// The Google Play release; null until live — surfaces render the
+  /// Android slot as "coming soon" while unset.
+  final String? play;
+
+  /// The product site.
+  final String site;
+
