+    expect(resolution.links.isDefault, isTrue);
+    expect(resolution.notes, isEmpty);
+  });
+
+  test('a user override wins (one change, every surface — AC1)', () async {
+    await writeConfig(
+      'provider: openai-completions\n'
+      'links:\n'
